// Keep only postings inside the lookback window, then shape them for a sheet.
// The date filter lives here rather than in the search because the Actor's
// timeRange input is rejected upstream on every value, so the search returns
// postings of all ages and they have to be trimmed after the fact.
const cfg = $('Set your hiring signal watch').first().json;
const weekOf = $now.toFormat('yyyy-MM-dd');
const maxAgeDays = Number(cfg.lookbackDays) || 30;

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

const rows = [];
for (const item of $input.all()) {
  const j = item.json;
  const posted = j.postedDate ? new Date(j.postedDate) : null;
  if (!posted || isNaN(posted)) continue;

  const ageDays = Math.floor(($now.toJSDate() - posted) / 86400000);
  if (ageDays > maxAgeDays || ageDays < 0) continue;

  rows.push({
    json: {
      'Week of': weekOf,
      'Job title': clip(j.title, 150),
      Company: j.companyName || '',
      Location: j.location || '',
      Posted: String(j.postedDate).slice(0, 10),
      'Days old': ageDays,
      Seniority: j.seniorityLevel || '',
      'Employment type': j.employmentType || '',
      'Job function': clip(j.jobFunction, 120),
      Applicants: typeof j.numApplicants === 'number' ? j.numApplicants : '',
      'Job link': j.jobUrl || '',
    },
  });
}
return rows;
